stops = ('TAA','TAG','TGA')
starts = ('ATG','GTG','TTG')

def translate_dna(s):
    return ''.join(CT[s[i:i+3]] for i in range(0, len(s)-(len(s)%3), 3))

def enumerate_orfs(s, strand_label, min_aa=60):
    out = []
    for frame in range(3):
        for k in range(frame, len(s)-2, 3):
            codon = s[k:k+3]
            if codon in starts:
                # extend to find the terminating stop
                j = k
                while j + 3 <= len(s) and s[j:j+3] not in stops:
                    j += 3
                aa_seq  = translate_dna(s[k:j])
                if len(aa_seq) >= min_aa:
                    out.append({'strand': strand_label, 'frame': frame+1,
                                'start0': k, 'stop0': j, 'length': len(aa_seq)*3,
                                'peptide': aa_seq})
    # merge duplicates: keep, per frame, the LONGEST ORF only (drop nested shorter ones)
    best = {}
    for o in out:
        key = (o['strand'], o['frame'])
        if key not in best or o['length'] > best[key]['length']:
            best[key] = o
    return list(best.values())

for o in sorted(enumerate_orfs(seq, '+'), key=lambda x: x['start0']):
